487	                $reactionWakeAt = $earliestArrival - $this->reactionLeadSeconds($seed);
488	                $saveable = false;
489	            } elseif ($secondsToImpact < self::REACTION_FLOOR_SECONDS) {
490	                $saveable = false;
491	            }
492	        }
493	
494	        // A save that fails is decided against a specific inbound fleet, so the same threat gets
495	        // the same judgement however many times the session re-reads it.
496	        if ($saveable) {
497	            $key = $inbound === [] ? 0 : (int) min(array_column($inbound, 'mission_id'));
498	            $skipReason = $this->saveFailurePolicy->shouldSkip($seed, $key);
499	
500	            if ($skipReason !== null) {
501	                return [
502	                    'fleetsave_eligible' => false,
503	                    'fleetsave_skip_reason' => $skipReason,
504	                    'inbound_fleets' => $inbound,
505	                    'reaction_wake_at' => null,
506	                ];
507	            }
508	        }
509	
510	        return [
511	            'fleetsave_eligible' => $saveable,
512	            'fleetsave_skip_reason' => null,
513	            'inbound_fleets' => $inbound,
514	            'reaction_wake_at' => $reactionWakeAt,
515	        ];
516	    }
517	
518	    /**
519	     * The seconds before impact the account wakes to react: a deterministic per-account draw
520	     * inside the 120–180 s window, so the same inbound always gets the same reaction and the
521	     * reaction never lands below the host's 10 s detector floor.
522	     */
523	    private function reactionLeadSeconds(?int $seed): int
524	    {
525	        $unit = $this->randomSource->unitInterval($seed ?? 0, 'reaction-wake');
526	
527	        return self::REACTION_WINDOW_MIN_SECONDS
528	            + (int) round((self::REACTION_WINDOW_MAX_SECONDS - self::REACTION_WINDOW_MIN_SECONDS) * $unit);
529	    }
530	
531	    /**
532	     * The recall is the other half of a save: the parked deployment comes home
533	     * once the hostile that sent it away is gone. A deployment between two own
534	     * bodies only, and never while the host still reports an attack.
535	     *
536	     * @return array{recall_eligible:bool}
537	     */
538	    private function recallState(int $playerId, bool $active, ?PlayerService $player): array
539	    {
540	        if (!$active || $player === null) {
541	            return ['recall_eligible' => false];
542	        }
543	
544	        $deploymentInFlight = FleetMission::query()
545	            ->where('user_id', $playerId)
546	            ->where('mission_type', DeploymentMission::getTypeId())
547	            ->where('canceled', 0)
548	            ->where('processed', 0)
549	            ->where('time_arrival', '>=', now()->timestamp)
550	            ->whereColumn('planet_id_from', '!=', 'planet_id_to')
551	            ->exists();
552	
553	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
554	
555	        return ['recall_eligible' => $deploymentInFlight && !$fleetMissions->currentPlayerUnderAttack()];
556	    }
557	}

